export default function SolicitudDeCita() {
  const [sent, setSent] = useState<null | { name: string; service: string; date: string; time: string }>(null);
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    setSent({ name: String(data.get("name") ?? ""), service: String(data.get("service") ?? ""), date: String(data.get("date") ?? ""), time: String(data.get("time") ?? "") });
  }
  const message = sent ? encodeURIComponent("Hola, soy " + sent.name + ". Quiero agendar " + sent.service + " el " + sent.date + " a las " + sent.time + ".") : "";
  return (
    <section id="agenda" className="bg-surface py-20 sm:py-28">
      <div className="mx-auto w-full max-w-6xl px-5 sm:px-8 grid gap-12 lg:grid-cols-2">
        <div>
          <div className="max-w-2xl">
          {content.eyebrow ? <p className="text-xs font-semibold uppercase tracking-[0.18em] text-primary">{content.eyebrow}</p> : null}
          <h2 className="mt-3 font-display text-3xl font-bold tracking-tight text-ink sm:text-4xl">{content.title}</h2>
          {content.subtitle ? <p className="mt-4 max-w-2xl text-base leading-relaxed text-muted sm:text-lg">{content.subtitle}</p> : null}
        </div>
          {content.note ? <p className="mt-6 flex items-start gap-2 text-sm text-muted"><CalendarCheck className="mt-0.5 size-4 shrink-0 text-primary" />{content.note}</p> : null}
        </div>
        {sent ? (
          <div className="rounded-card border border-line bg-surface p-6 shadow-card flex flex-col items-start gap-4">
            <CheckCircle2 className="size-8 text-primary" />
            <p className="font-display text-xl font-semibold text-ink">¡Gracias, {sent.name}!</p>
            <p className="text-sm text-muted">Recibimos tu solicitud para {sent.service} el {sent.date} a las {sent.time}. Te confirmamos a la brevedad.</p>
            {content.whatsapp ? <a href={"https://wa.me/" + content.whatsapp + "?text=" + message} className="inline-flex items-center justify-center gap-2 rounded-btn bg-primary px-6 py-3 text-sm font-semibold text-primary-ink shadow-card transition hover:-translate-y-0.5 hover:opacity-95">Confirmar por WhatsApp</a> : null}
            <button type="button" onClick={() => setSent(null)} className="text-sm font-semibold text-primary">Agendar otra</button>
          </div>
        ) : (
          <form onSubmit={submit} className="rounded-card border border-line bg-surface p-6 shadow-card grid gap-4 sm:grid-cols-2">
            <label className="grid gap-1.5 text-sm font-medium text-ink sm:col-span-2">Nombre<input required name="name" className="rounded-input border border-line bg-bg px-4 py-3 text-sm text-ink outline-none focus:border-primary" /></label>
            <label className="grid gap-1.5 text-sm font-medium text-ink sm:col-span-2">Servicio
              <select required name="service" className="rounded-input border border-line bg-bg px-4 py-3 text-sm text-ink outline-none focus:border-primary">
                {content.options.map((option) => <option key={option}>{option}</option>)}
              </select>
            </label>
            <label className="grid gap-1.5 text-sm font-medium text-ink">Fecha<input required type="date" name="date" className="rounded-input border border-line bg-bg px-4 py-3 text-sm text-ink outline-none focus:border-primary" /></label>
            <label className="grid gap-1.5 text-sm font-medium text-ink">Hora<input required type="time" name="time" className="rounded-input border border-line bg-bg px-4 py-3 text-sm text-ink outline-none focus:border-primary" /></label>
